public double averageWithinRange(double lower, double upper) {
    double sum = 0.0;
    int count = 0;
    for (ItemInfo item : inventory) {
        if (item.isAvailable() && item.getCost() >= lower && item.getCost() <= upper) {
            sum += item.getCost();
            count++;
        }
    }
    return sum / count;
}

