public String playerWithClosestScore(int targetScore) {
    Player best = playerList.get(0);
    double bestDifference = Math.abs((double) best.getScore() - targetScore);
    for (Player player : playerList) {
        double difference = Math.abs((double) player.getScore() - targetScore);
        if (difference < bestDifference) {
            best = player;
            bestDifference = difference;
        }
    }
    return best.getID();
}

