public int countOrderedRows() {
    int count = 0;
    for (int r = 0; r < grid.length; r++) {
        boolean ordered = true;
        for (int c = 1; c < grid[r].length; c++) {
            if (grid[r][c].length() < grid[r][c - 1].length()) {
                ordered = false;
            }
        }
        if (ordered) { count++; }
    }
    return count;
}

