public boolean isBalanced(ArrayList<String> delimiters) {
    int balance = 0;
    for (String delimiter : delimiters) {
        if (delimiter.equals(openDel)) { balance++; }
        else { balance--; }
        if (balance < 0) { return false; }
    }
    return balance == 0;
}

